"""Generate the static Vellbyte company site. No runtime dependencies."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parent
SITE = 'https://vellbyte.com'
# The original support site is available over verified HTTPS. A local mirror
# remains available at /support/ as a fallback.
SUPPORT = 'https://support.vellbyte.com'
FB = 'https://www.facebook.com/profile.php?id=61595829853886'
YT = 'https://www.youtube.com/@vellbyteapps'
IG = 'https://www.instagram.com/vellbyteapps/'
X_PROFILE = 'https://x.com/vellbyteapps'

nav = [('Apps','/apps/'), ('Services','/services/'), ('About','/about/'), ('Testing','/testing/'), ('Contact','/contact/')]

def button(href, text, secondary=False):
    return f'<a class="button {"button-secondary" if secondary else "button-primary"}" href="{escape(href, quote=True)}">{escape(text)}<span aria-hidden="true">↗</span></a>'

def status():
    return '<span class="status"><span aria-hidden="true"></span> In development</span>'

def brand():
    return '<a class="brand" href="/" aria-label="Vellbyte home"><img src="/assets/logo-horizontal.svg" width="159" height="36" alt="Vellbyte"></a>'

def header(path):
    links = ''.join('<a href="{}"{}>{}</a>'.format(u, ' aria-current="page"' if path.startswith(u) else '', n) for n,u in nav)
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner">{brand()}<nav class="main-nav" aria-label="Main navigation">{links}</nav><a class="header-cta" href="/apps/">Explore our apps <span aria-hidden="true">↗</span></a></div></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="shell"><div class="footer-top"><div><a class="footer-wordmark" href="/">Vellbyte<span class="word-dot">.</span></a><p>Useful apps for everyday life.</p></div><div class="footer-col"><strong>Explore</strong><a href="/apps/">Our apps</a><a href="/services/">App-building services</a><a href="/about/">About</a><a href="/testing/">Testing information</a></div><div class="footer-col"><strong>Get in touch</strong><a href="/contact/">Contact</a><a href="{SUPPORT}/">App support drafts <span aria-hidden="true">↗</span></a><a href="{FB}">Facebook <span aria-hidden="true">↗</span></a><a href="{YT}">YouTube <span aria-hidden="true">↗</span></a><a href="{IG}">Instagram <span aria-hidden="true">↗</span></a><a href="{X_PROFILE}">X <span aria-hidden="true">↗</span></a></div><div class="footer-col"><strong>Information</strong><a href="/privacy/">Website privacy</a><a href="{SUPPORT}/trip-split-privacy.html">Trip Split privacy draft <span aria-hidden="true">↗</span></a><a href="{SUPPORT}/pack-planner-privacy.html">Pack Planner privacy draft <span aria-hidden="true">↗</span></a></div></div><div class="footer-bottom"><span>© 2026 Vellbyte</span><span>Made for the everyday.</span></div></div></footer>'''

def document(title, description, body, path='/', image='/assets/share.png'):
    canonical=SITE+path
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{escape(title)} | Vellbyte</title><meta name="description" content="{escape(description, quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="Vellbyte"><meta property="og:title" content="{escape(title, quote=True)} | Vellbyte"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{SITE}{image}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"></head><body>{header(path)}<main id="main">{body}</main>{footer()}</body></html>'''

def image_phone(file, alt, klass=''):
    return f'<figure class="phone {klass}"><div class="phone-screen"><img src="/assets/{file}" alt="{escape(alt, quote=True)}" width="1080" height="1920" loading="lazy"></div></figure>'

def screen_pair():
    return f'''<div class="hero-art" aria-label="Development previews of Vellbyte apps using sample data"><div class="art-ring ring-one"></div><div class="art-ring ring-two"></div><div class="art-label label-one"><span>01 / PLAN</span><strong>Go prepared.</strong></div><div class="art-label label-two"><span>02 / SHARE</span><strong>Keep it clear.</strong></div>{image_phone('pack-trip.png','Pack Planner trip details showing a sample packing list','phone-back')}{image_phone('trip-balances.png','Trip Split sample trip balances on an Android development build','phone-front')}<span class="art-note">Real app screens · sample data</span></div>'''

def app_card(kind, heading_level=3):
    if kind == 'trip':
        return f'''<article class="app-card trip-card"><div class="app-copy"><div class="app-card-top"><img src="/assets/trip-icon.png" alt="" width="58" height="58"><span class="app-number">01 / GROUP TRAVEL</span></div>{status()}<h{heading_level}>Trip Split</h{heading_level}><p>A clear view of shared expenses, balances, and who paid what.</p><a class="text-link" href="/apps/trip-split/">Explore Trip Split <span aria-hidden="true">↗</span></a></div><div class="app-card-image">{image_phone('trip-expenses.png','Trip Split sample expense list on an Android development build')}</div></article>'''
    return f'''<article class="app-card pack-card"><div class="app-copy"><div class="app-card-top"><img src="/assets/pack-icon.png" alt="" width="58" height="58"><span class="app-number">02 / PACKING</span></div>{status()}<h{heading_level}>Pack Planner</h{heading_level}><p>Make a list, pack at your own pace, and keep track of what’s left.</p><a class="text-link" href="/apps/pack-planner/">Explore Pack Planner <span aria-hidden="true">↗</span></a></div><div class="app-card-image">{image_phone('pack-trip.png','Pack Planner sample trip details on an Android development build')}</div></article>'''

home = f'''<section class="hero shell"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-dot"></span> INDEPENDENT APP STUDIO</div><h1>Make room for <em>more life.</em></h1><p class="hero-sub">Useful apps for everyday life.</p><p class="lead">A little less juggling. A little more living. We’re building thoughtful tools for the things you do every day.</p><div class="actions">{button('/apps/','Explore our apps')}{button('/about/','Meet Vellbyte',True)}</div><div class="hero-foot"><span>BUILT WITH PURPOSE</span><span>EST. FOR EVERYDAY</span></div></div>{screen_pair()}</section>
<section class="section collection" id="apps"><div class="shell"><div class="section-top"><div><div class="eyebrow">THE FIRST COLLECTION</div><h2>Small tools.<br><em>Big breathing room.</em></h2></div><p>From the first packing list to the final shared expense, our apps are designed to make everyday moments easier to manage.</p></div><div class="app-grid">{app_card('trip')}{app_card('pack')}</div><div class="caption">Development previews shown with fictional sample data. App availability will be shared when confirmed.</div></div></section>
<section class="section service-intro"><div class="shell service-intro-inner"><div><div class="eyebrow">BUILD WITH VELLBYTE</div><h2>Have an app idea?<br><em>Let’s talk about it.</em></h2><p class="lead">Alongside our own apps, we offer app-building services for people and businesses with ideas to explore.</p></div><div><p>Tell us what you want to build, who it’s for, and where you are in the process. We’ll discuss the project and what it might need.</p>{button('/services/','Explore our services')}</div></div></section>
<section class="section principles"><div class="shell principle-layout"><div><div class="eyebrow eyebrow-light">OUR APPROACH</div><h2>Useful by design.<br><em>Human by nature.</em></h2></div><div class="principle-copy"><p>Life is already full of details. Our aim is to build focused apps that help you keep track of a few of them—with less noise along the way.</p><a class="light-link" href="/about/">Get to know Vellbyte <span aria-hidden="true">↗</span></a></div></div></section>
<section class="section next"><div class="shell next-inner"><div><div class="eyebrow">STAY IN THE LOOP</div><h2>Curious about what’s next?</h2><p>See what we’re building and how we’re approaching testing.</p></div>{button('/testing/','Testing information')}</div></section>'''

apps = f'''<section class="page-hero shell"><div class="eyebrow">OUR APPS <span> / 01</span></div><h1>Less to manage.<br><em>More to enjoy.</em></h1><p class="lead">A growing collection of focused tools for plans, lists, and the details in between.</p></section><section class="section compact-section"><div class="shell"><div class="app-grid">{app_card('trip', 2)}{app_card('pack', 2)}</div><p class="caption">Both apps are in development. The screens shown are from Android development builds with fictional sample data; store availability is not yet confirmed.</p></div></section>'''

def product(kind):
    trip=kind=='trip'
    name='Vellbyte Trip Split' if trip else 'Vellbyte Pack Planner'
    kicker='01 / GROUP TRAVEL' if trip else '02 / PACKING'
    heading='Share the trip.<br><em>Keep the math clear.</em>' if trip else 'Pack for the trip.<br><em>Leave the guesswork.</em>'
    copy='Keep a shared trip’s expenses organized, see balances, and record settlements in one place.' if trip else 'Build packing lists around your trips, check off items, and reuse the lists that work for you.'
    hero='trip-balances.png' if trip else 'pack-trip.png'
    imgalt='A sample Trip Split trip showing participant balances' if trip else 'A sample Pack Planner trip showing a packing checklist'
    shot2='trip-expenses.png' if trip else 'pack-items.png'
    alt2='A fictional Trip Split trip expense list' if trip else 'Sample Pack Planner items with packing controls'
    points=[('01','Track expenses','Record who paid and choose the people sharing each expense.'),('02','See the balance','Review each person’s share and the resulting balances.'),('03','Record settling up','Keep a record of settlements and share a trip summary.')] if trip else [('01','Make it yours','Create trips with place labels, dates, notes, categories, and quantities.'),('02','Pack at your pace','Check items off and see your progress as you go.'),('03','Use a list again','Save reusable lists and start a new trip from them.')]
    lim='Trip Split records expenses and settlements; it does not send money or convert currencies. Trips do not sync between devices.' if trip else 'Pack Planner stores its lists on the device and does not provide live travel or weather information.'
    items=''.join(f'<article class="feature-item"><span>{n}</span><h3>{t}</h3><p>{d}</p></article>' for n,t,d in points)
    url='trip-split' if trip else 'pack-planner'
    return f'''<section class="product-hero shell"><div class="product-copy"><div class="eyebrow">{kicker}</div><div class="product-heading-meta"><strong class="product-name">{name}</strong>{status()}</div><h1>{heading}</h1><p class="lead">{copy}</p><div class="actions">{button('/testing/','Testing information')}{button('/contact/','Get in touch',True)}</div><p class="subnote">In development. Download links will appear when availability is verified.</p></div><div class="product-visual {"trip-visual" if trip else "pack-visual"}"><span class="visual-index">A LITTLE MORE CLARITY / {"01" if trip else "02"}</span>{image_phone(hero,imgalt)}<span class="art-note">Real Android development screen · sample data</span></div></section><section class="section feature-section"><div class="shell"><div class="section-top"><div><div class="eyebrow">HOW IT HELPS</div><h2>Made for the<br><em>details that matter.</em></h2></div><p>Simple steps for a more organized {"trip together" if trip else "departure"}.</p></div><div class="feature-grid">{items}</div></div></section><section class="section app-detail"><div class="shell detail-grid"><div class="detail-surface {"trip-surface" if trip else "pack-surface"}">{image_phone(shot2,alt2)}</div><div><div class="eyebrow">GOOD TO KNOW</div><h2>Thoughtful about<br><em>the essentials.</em></h2><p class="lead">{lim}</p><p>We’re preparing {name} for release. Features and availability may change as development continues.</p><a class="text-link" href="{SUPPORT}/{url}-support.html">Product support draft <span aria-hidden="true">↗</span></a><br><a class="text-link secondary-link" href="{SUPPORT}/{url}-privacy.html">Product privacy draft <span aria-hidden="true">↗</span></a></div></div></section><section class="next product-next"><div class="shell next-inner"><div><div class="eyebrow">KEEP EXPLORING</div><h2>Discover the other little helper.</h2><p>See the rest of the Vellbyte collection.</p></div>{button('/apps/','All apps')}</div></section>'''

about = '''<section class="page-hero shell"><div class="eyebrow">ABOUT VELLBYTE <span> / 02</span></div><h1>Made for the<br><em>everyday moments.</em></h1><p class="lead">We believe the best tools make space for the things you actually want to do.</p></section><section class="section about-story"><div class="shell editorial-grid"><div class="big-mark" aria-hidden="true"><img src="/assets/symbol.svg" alt=""></div><div><div class="eyebrow">A LITTLE ABOUT US</div><h2>Simple ideas.<br><em>Useful outcomes.</em></h2><p class="lead">Vellbyte is an independent app studio building practical tools for everyday life and offering app-building services.</p><p>We’re starting with two familiar challenges: keeping shared trip expenses clear and remembering what to pack. Our approach is to focus on the useful details, keep the experience approachable, and make each app easy to understand.</p><a class="text-link" href="/apps/">Explore what we’re building <span aria-hidden="true">↗</span></a></div></div></section><section class="section compact-section"><div class="shell feature-grid"><article class="feature-item"><span>01</span><h3>Purpose first.</h3><p>Start with an everyday problem and stay focused on the task.</p></article><article class="feature-item"><span>02</span><h3>Thoughtful details.</h3><p>Make the small interactions feel clear and considered.</p></article><article class="feature-item"><span>03</span><h3>Room to grow.</h3><p>Keep learning as our apps move through development.</p></article></div></section>'''

services = f'''<section class="page-hero shell"><div class="eyebrow">APP-BUILDING SERVICES</div><h1>Your idea.<br><em>Let’s build on it.</em></h1><p class="lead">Vellbyte offers app-building services for people and businesses who want to turn an idea into a useful digital product.</p><div class="actions">{button('mailto:contact@vellbyte.com?subject=App%20project%20inquiry','Tell us about your project')}{button('/apps/','See our apps in development',True)}</div></section>
<section class="section service-details"><div class="shell"><div class="section-top"><div><div class="eyebrow">WHERE TO START</div><h2>From a rough idea<br><em>to a clearer plan.</em></h2></div><p>Every project is different. We can discuss the help you’re looking for and agree on a scope that fits the idea.</p></div><div class="feature-grid"><article class="feature-item"><span>01</span><h3>Shape the idea</h3><p>Talk through the problem, the people you want to help, and the features that matter most.</p></article><article class="feature-item"><span>02</span><h3>Design the experience</h3><p>Explore how the app could be organized and how people might use it.</p></article><article class="feature-item"><span>03</span><h3>Build and refine</h3><p>Discuss development, testing, and next steps based on the needs of your project.</p></article></div></div></section>
<section class="section compact-section"><div class="shell prose-layout"><div><div class="eyebrow">START A CONVERSATION</div><h2>Tell us what<br><em>you have in mind.</em></h2></div><div class="prose"><p>Share a short description of your idea, who it’s for, and any timing or budget considerations you’d like us to know. It’s fine if you’re still figuring things out.</p><p>We’ll discuss the details, including scope, timing, and cost, before any work is agreed. Please don’t include passwords, payment details, or other sensitive information in your email.</p><a class="text-link" href="mailto:contact@vellbyte.com?subject=App%20project%20inquiry">Email contact@vellbyte.com <span aria-hidden="true">↗</span></a></div></div></section>'''

contact = f'''<section class="page-hero shell"><div class="eyebrow">CONTACT <span> / 03</span></div><h1>Let’s keep<br><em>in touch.</em></h1><p class="lead">Questions about Vellbyte, our apps, or a project you’d like to build? We’d like to hear from you.</p></section><section class="section compact-section"><div class="shell contact-grid"><article class="contact-card"><span class="contact-num">01 / SAY HELLO</span><h2>General inquiries</h2><p>For company questions, ideas, and general inquiries.</p><a class="text-link" href="mailto:contact@vellbyte.com">contact@vellbyte.com <span aria-hidden="true">↗</span></a></article><article class="contact-card"><span class="contact-num">02 / BUILD WITH US</span><h2>App projects</h2><p>Tell us about your idea and discuss app-building services.</p><a class="text-link" href="mailto:contact@vellbyte.com?subject=App%20project%20inquiry">Email about your project <span aria-hidden="true">↗</span></a><a class="text-link secondary-link" href="/services/">Explore services <span aria-hidden="true">↗</span></a></article><article class="contact-card"><span class="contact-num">03 / NEED A HAND?</span><h2>App support</h2><p>For questions about a Vellbyte app, visit our support drafts or email our support address.</p><a class="text-link" href="{SUPPORT}/">Visit support drafts <span aria-hidden="true">↗</span></a><a class="text-link secondary-link" href="mailto:support@vellbyte.com">support@vellbyte.com <span aria-hidden="true">↗</span></a></article></div><div class="shell contact-note"><p>For your privacy, please avoid including passwords, payment details, or other sensitive information in email.</p></div></section>'''

testing = '''<section class="page-hero shell"><div class="eyebrow">TESTING INFORMATION <span> / 04</span></div><h1>Good things take<br><em>a little testing.</em></h1><p class="lead">We’re preparing our first apps and working through the details before release.</p></section><section class="section compact-section"><div class="shell prose-layout"><div><div class="eyebrow">WHAT TO EXPECT</div><h2>Thoughtful feedback<br><em>makes a difference.</em></h2></div><div class="prose"><p>Vellbyte Trip Split and Vellbyte Pack Planner are in development. Testing and public download options will be shared when they’re available.</p><p>Interested in learning more? Send us a note with the app you’re interested in and the device you use. Please don’t include sensitive information.</p><a class="text-link" href="mailto:contact@vellbyte.com?subject=Vellbyte%20testing%20information">Ask about testing <span aria-hidden="true">↗</span></a><p class="small-note">This is an information request, not an enrollment or invitation.</p></div></div></section>'''

privacy = '''<section class="page-hero shell"><div class="eyebrow">WEBSITE PRIVACY <span> / 05</span></div><h1>Clear information,<br><em>simply put.</em></h1><p class="lead">How this company website handles information.</p></section><section class="section compact-section"><div class="shell narrow prose"><p><strong>Last updated November 1, 2026</strong></p><h2>Using this site</h2><p>This website presents information about Vellbyte, its apps, and its services. It has no account registration, web forms, advertising pixels, or analytics tools configured in the site itself.</p><p>The hosting provider may process routine technical information, such as IP addresses and request logs, to deliver and secure the site. Your browser may also retain ordinary cached files.</p><h2>Emailing us</h2><p>When you choose an email link, your email app opens a message addressed to us. We receive the information you choose to send and use it to respond. Email is not a secure channel for passwords, payment information, or other sensitive details.</p><h2>Other sites and apps</h2><p>Some links lead to social networks and other services with their own practices. App support and privacy drafts are available on our support site; each app has its own privacy information, which is still under review.</p><h2>Questions</h2><p>Contact <a href="mailto:contact@vellbyte.com">contact@vellbyte.com</a> with website privacy questions.</p></div></section>'''

pages={
    'index.html':('Useful apps for everyday life','Vellbyte is an independent app studio building practical tools and offering app-building services.',home,'/'),
    'apps/index.html':('Our apps','Explore Vellbyte Trip Split and Vellbyte Pack Planner, two apps in development for more organized trips.',apps,'/apps/'),
    'apps/trip-split/index.html':('Trip Split','Organize shared trip expenses and see balances with Vellbyte Trip Split, currently in development.',product('trip'),'/apps/trip-split/'),
    'apps/pack-planner/index.html':('Pack Planner','Make reusable packing lists and track what is packed with Vellbyte Pack Planner, currently in development.',product('pack'),'/apps/pack-planner/'),
    'about/index.html':('About','Meet Vellbyte, an independent app studio building practical tools for everyday life.',about,'/about/'),
    'services/index.html':('App-building services','Discuss your app idea with Vellbyte, from early planning and design to development and testing.',services,'/services/'),
    'contact/index.html':('Contact','Get in touch with Vellbyte or find support for our apps.',contact,'/contact/'),
    'testing/index.html':('Testing information','Learn about the status of Vellbyte apps and ask about future testing information.',testing,'/testing/'),
    'privacy/index.html':('Website privacy','Read how the Vellbyte company website handles information.',privacy,'/privacy/'),
}

for name,(title,description,body,path) in pages.items():
    p=ROOT/name; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(document(title,description,body,path),encoding='utf-8')
print(f'Generated {len(pages)} pages in {ROOT}')
